<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Sorting Visualizer</title>
<style>
  :root {
    --bg: #0f1115;
    --panel: #171a21;
    --line: #262b36;
    --text: #e6e9ef;
    --muted: #8b93a7;
    --accent: #5aa9ff;
    --accent-2: #7ee787;
    --warn: #ffb454;
  }
  * { box-sizing: border-box; }
  html, body { height: 100%; }
  body {
    margin: 0;
    background: var(--bg);
    color: var(--text);
    font: 14px/1.5 ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 24px 16px 32px;
  }
  h1 {
    font-size: 18px;
    font-weight: 600;
    letter-spacing: .02em;
    margin: 0 0 4px;
  }
  .sub { color: var(--muted); margin: 0 0 18px; font-size: 12px; }
  .app {
    width: min(1000px, 100%);
    background: var(--panel);
    border: 1px solid var(--line);
    border-radius: 12px;
    padding: 16px;
  }
  .controls {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    align-items: center;
    margin-bottom: 14px;
  }
  button {
    background: #1e2430;
    color: var(--text);
    border: 1px solid var(--line);
    border-radius: 8px;
    padding: 8px 14px;
    font: inherit;
    font-weight: 500;
    cursor: pointer;
    transition: background .15s, border-color .15s, transform .05s;
  }
  button:hover { background: #262e3d; border-color: #3a4356; }
  button:active { transform: translateY(1px); }
  button:disabled { opacity: .5; cursor: not-allowed; }
  #sort { border-color: #2c4c74; background: #16273b; }
  #sort:hover { background: #1b3committed; }
  #sort:hover { background: #1b3049; }
  .spacer { flex: 1; }
  .stat { color: var(--muted); font-variant-numeric: tabular-nums; font-size: 12px; }
  .stat b { color: var(--text); font-weight: 600; }
  #bars {
    display: flex;
    align-items: flex-end;
    gap: 2px;
    height: 340px;
    padding: 8px;
    background: #10131a;
    border: 1px solid var(--line);
    border-radius: 8px;
    overflow: hidden;
  }
  .bar {
    flex: 1 1 0;
    min-width: 2px;
    background: linear-gradient(180deg, var(--accent), #2f6fb3);
    border-radius: 2px 2px 0 0;
    transition: height .08s linear;
  }
  .bar.active { background: linear-gradient(180deg, var(--warn), #b8742a); }
  .bar.done { background: linear-gradient(180deg, var(--accent-2), #3d8a4c); }
  footer { color: var(--muted); font-size: 12px; margin-top: 12px; }
  code { color: #b8c2d6; }
</style>
</head>
<body>
  <h1>Sorting Visualizer</h1>
  <p class="sub">Bubble sort, one comparison per step.</p>

  <div class="app">
    <div class="controls">
      <button id="sort">Sort</button>
      <button id="shuffle">Shuffle</button>
      <button id="reset">Reset</button>
      <span class="spacer"></span>
      <span class="stat">steps <b id="steps">0</b> · swaps <b id="swaps">0</b> · n <b id="n">0</b></span>
    </div>
    <div id="bars"></div>
    <footer>API: <code>window.viz.array() / setArray(a) / sortStep() / sorted()</code></footer>
  </div>

<script>
(function () {
  'use strict';

  var barsEl   = document.getElementById('bars');
  var stepsEl  = document.getElementById('steps');
  var swapsEl  = document.getElementById('swaps');
  var nEl      = document.getElementById('n');
  var sortBtn  = document.getElementById('sort');
  var shufBtn  = document.getElementById('shuffle');
  var resetBtn = document.getElementById('reset');

  var DEFAULT_N = 40;
  var array = [];
  var initial = [];
  var bars = [];

  // bubble-sort cursor
  var i = 0, j = 0;
  var finished = false;
  var steps = 0, swaps = 0;
  var timer = null;
  var lastTouched = -1;

  function makeArray(n) {
    var a = [];
    for (var k = 0; k < n; k++) a.push(k + 1);
    return shuffled(a);
  }

  function shuffled(a) {
    var b = a.slice();
    for (var k = b.length - 1; k > 0; k--) {
      var r = Math.floor(Math.random() * (k + 1));
      var t = b[k]; b[k] = b[r]; b[r] = t;
    }
    return b;
  }

  function resetCursor() {
    i = 0; j = 0;
    finished = array.length <= 1;
    steps = 0; swaps = 0;
    lastTouched = -1;
  }

  function build() {
    barsEl.innerHTML = '';
    bars = [];
    for (var k = 0; k < array.length; k++) {
      var d = document.createElement('div');
      d.className = 'bar';
      barsEl.appendChild(d);
      bars.push(d);
    }
    draw();
  }

  function draw() {
    var max = 1;
    for (var k = 0; k < array.length; k++) {
      var v = Number(array[k]);
      if (isFinite(v) && v > max) max = v;
    }
    for (var k2 = 0; k2 < bars.length; k2++) {
      var val = Number(array[k2]);
      if (!isFinite(val)) val = 0;
      var pct = max > 0 ? Math.max(1, (val / max) * 100) : 1;
      bars[k2].style.height = pct + '%';
      bars[k2].className = 'bar';
      if (finished) bars[k2].className = 'bar done';
      else if (k2 === lastTouched || k2 === lastTouched + 1) bars[k2].className = 'bar active';
    }
    stepsEl.textContent = steps;
    swapsEl.textContent = swaps;
    nEl.textContent = array.length;
  }

  function isSorted() {
    for (var k = 1; k < array.length; k++) {
      if (Number(array[k - 1]) > Number(array[k])) return false;
    }
    return true;
  }

  // Exactly one comparison (and possible swap) per call.
  function sortStep() {
    if (finished || array.length <= 1) { finished = true; return true; }

    var end = array.length - 1 - i;
    if (j >= end) {
      j = 0;
      i++;
      if (i >= array.length - 1 || isSorted()) {
        finished = true;
        lastTouched = -1;
        return true;
      }
      end = array.length - 1 - i;
    }

    steps++;
    lastTouched = j;
    if (Number(array[j]) > Number(array[j + 1])) {
      var t = array[j]; array[j] = array[j + 1]; array[j + 1] = t;
      swaps++;
    }
    j++;

    if (j >= array.length - 1 - i) {
      j = 0;
      i++;
      if (i >= array.length - 1 || isSorted()) {
        finished = true;
        lastTouched = -1;
      }
    }
    return finished;
  }

  function stopAnim() {
    if (timer !== null) { clearInterval(timer); timer = null; }
    sortBtn.textContent = 'Sort';
  }

  function animate() {
    if (timer !== null) { stopAnim(); return; }
    if (finished) return;
    sortBtn.textContent = 'Pause';
    timer = setInterval(function () {
      // several comparisons per frame so it stays lively on bigger arrays
      var budget = Math.max(1, Math.ceil(array.length / 12));
      var done = false;
      for (var k = 0; k < budget && !done; k++) done = sortStep();
      draw();
      if (done) stopAnim();
    }, 16);
  }

  sortBtn.addEventListener('click', animate);

  shufBtn.addEventListener('click', function () {
    stopAnim();
    array = shuffled(array.length ? array : makeArray(DEFAULT_N));
    initial = array.slice();
    resetCursor();
    build();
  });

  resetBtn.addEventListener('click', function () {
    stopAnim();
    array = initial.slice();
    resetCursor();
    build();
  });

  window.viz = {
    array: function () { return array.slice(); },
    setArray: function (a) {
      stopAnim();
      array = Array.prototype.slice.call(a).map(Number);
      initial = array.slice();
      resetCursor();
      build();
      return array.slice();
    },
    sortStep: function () {
      var done = sortStep();
      draw();
      return done;
    },
    sorted: function () { return isSorted(); }
  };

  array = makeArray(DEFAULT_N);
  initial = array.slice();
  resetCursor();
  build();
})();
</script>
</body>
</html>
